// Define how Sequelize represents one row from the favorites table. DataTypes
// describes each column, and the shared Sequelize instance connects this model
// to the configured database.
import { DataTypes } from "sequelize";
import sequelize from "../config/db.js";

// This model describes the existing favorites table; it does not create or
// alter it. Attribute names match the existing snake_case column names.
const Favorite = sequelize.define(
  "Favorite",
  {
    // Primary key generated by the database when a row is inserted.
    id: {
      type: DataTypes.BIGINT.UNSIGNED,
      primaryKey: true,
      autoIncrement: true,
      allowNull: false,
    },
    // Owner of the favorite; deleting the user deletes their favorites.
    user_id: {
      type: DataTypes.BIGINT.UNSIGNED,
      allowNull: false,
      references: { model: "users", key: "id" },
      onUpdate: "CASCADE",
      onDelete: "CASCADE",
    },
    // Optional catalog link; mock and API exercises may have no local row.
    exercise_id: {
      type: DataTypes.INTEGER,
      allowNull: true,
      references: { model: "exercises", key: "id" },
      onUpdate: "CASCADE",
      onDelete: "RESTRICT",
    },
    // Which data source the saved exercise came from.
    source: {
      type: DataTypes.ENUM("backend", "mock", "api"),
      allowNull: false,
    },
    // The exercise's identifier within its source.
    source_exercise_id: {
      type: DataTypes.STRING(191),
      allowNull: false,
    },
    // A copy of the details keeps favorites displayable without the source.
    exercise_snapshot: {
      type: DataTypes.JSON,
      allowNull: false,
    },
    created_at: {
      type: DataTypes.DATE(3),
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
  },
  {
    // Explicit mapping avoids Sequelize guessing a table name.
    tableName: "favorites",
    // Only created_at exists; this table has no updated_at column.
    timestamps: true,
    createdAt: "created_at",
    updatedAt: false,
    // Match the unique and lookup indexes created by the migration.
    indexes: [
      {
        name: "favorites_user_source_exercise_unique",
        unique: true,
        fields: ["user_id", "source", "source_exercise_id"],
      },
      {
        name: "favorites_user_created",
        fields: ["user_id", "created_at"],
      },
      {
        name: "favorites_exercise",
        fields: ["exercise_id"],
      },
    ],
  }
);

export default Favorite;
